import{_ as t,o as s,c as a,a2 as o}from"./chunks/framework.CyZTVJbV.js";const u=JSON.parse('{"title":"Fidelity — dogfood-ably-collab-cursor (v1.13-4)","description":"","frontmatter":{},"headers":[],"relativePath":"quality-reports/realtime/ably-collab-cursor.md","filePath":"quality-reports/realtime/ably-collab-cursor.md"}'),i={name:"quality-reports/realtime/ably-collab-cursor.md"};function r(d,e,n,l,c,p){return s(),a("div",null,[...e[0]||(e[0]=[o(`<h1 id="fidelity-—-dogfood-ably-collab-cursor-v1-13-4" tabindex="-1">Fidelity — dogfood-ably-collab-cursor (v1.13-4) <a class="header-anchor" href="#fidelity-—-dogfood-ably-collab-cursor-v1-13-4" aria-label="Permalink to &quot;Fidelity — dogfood-ably-collab-cursor (v1.13-4)&quot;">​</a></h1><p>Real-vs-mock behavioural fidelity for the Ably collaborative-cursor dogfood, produced by <code>examples/dogfood-ably-collab-cursor/tests/emit-fidelity-report.test.ts</code>. Feeds <code>@kiwa/quality-metrics</code> 7-axis release gate.</p><h2 id="baseline-real-mode-skipped-—-no-ably-api-key" tabindex="-1">Baseline (real mode skipped — no <code>ABLY_API_KEY</code>) <a class="header-anchor" href="#baseline-real-mode-skipped-—-no-ably-api-key" aria-label="Permalink to &quot;Baseline (real mode skipped — no \`ABLY_API_KEY\`)&quot;">​</a></h2><p>When the harness runs without Ably credentials, the real adapter emits <code>ABLY_ENV_MISSING</code> for every op. Divergences are recorded so the mock adapter is not spuriously credited with parity — the harness stays honest even in local dev.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>provider   : @kiwa/realtime/ably-collab-cursor</span></span>
<span class="line"><span>version    : 0.1.0</span></span>
<span class="line"><span>verdict    : PASS</span></span>
<span class="line"><span>divergences: 4 (joinBoard / moveCursor / rewindHistory / getPresence — recorded as BEHAVIORAL_DIVERGENCE, real mode absent)</span></span>
<span class="line"><span>axes       : 7 (common branch — realtime is not a token-priced generative surface)</span></span></code></pre></div><table tabindex="0"><thead><tr><th>axis</th><th>actual</th><th>threshold</th><th>verdict</th></tr></thead><tbody><tr><td>coverage.line</td><td>92.00%</td><td>85%</td><td>pass</td></tr><tr><td>coverage.branch</td><td>88.00%</td><td>80%</td><td>pass</td></tr><tr><td>coverage.function</td><td>95.00%</td><td>90%</td><td>pass</td></tr><tr><td>fidelity.ratio</td><td>100.00% (4/4)</td><td>70%</td><td>pass</td></tr><tr><td>perf.p95Ms</td><td>4.00 ms</td><td>100 ms</td><td>pass</td></tr><tr><td>mutation.killRate</td><td>70.00% (28/40)</td><td>60%</td><td>pass</td></tr><tr><td>testCount.behavior</td><td>15</td><td>10</td><td>pass</td></tr></tbody></table><p>The <code>divergences</code> count in the notes section counts every op whose mock path succeeded but whose real path threw <code>ABLY_ENV_MISSING</code> — this is expected in a real-mode-skipped baseline and does not itself fail the gate (fidelity ratio measures the mock-covered surface area, which is 100% for the 4 ops the AC scopes).</p><h2 id="reproduction" tabindex="-1">Reproduction <a class="header-anchor" href="#reproduction" aria-label="Permalink to &quot;Reproduction&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --filter</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dogfood-ably-collab-cursor</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cat</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> examples/dogfood-ably-collab-cursor/quality-report/fidelity-latest.md</span></span></code></pre></div><p>Live real-mode.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ABLY_API_KEY</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">your-ably-api-key</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ABLY_CLIENT_ID</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">optional-client-id</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --filter</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dogfood-ably-collab-cursor</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span></span></code></pre></div><p>When the env is set but <code>ably</code> is not vendored into the workspace (the default in this example), the adapter downgrades to <code>ABLY_SDK_MISSING</code> traces. Adding the dependency + wiring the connected paths in <code>src/adapters/real.ts</code> is a follow-up when a real Ably project is provisioned — the adapter shape is ready.</p><h2 id="ops-under-measurement" tabindex="-1">Ops under measurement <a class="header-anchor" href="#ops-under-measurement" aria-label="Permalink to &quot;Ops under measurement&quot;">​</a></h2><p>Four provider-neutral ops on <code>CursorBoardAdapter</code>.</p><ul><li><code>joinBoard</code> — subscribe to a board channel + presence enter for a user</li><li><code>moveCursor</code> — broadcast a cursor position burst, throttled at 60 fps (16 ms window) so mass mousemove events do not flood the channel</li><li><code>rewindHistory</code> — pull the last N cursor events from <code>channel.history</code> so a late-joining user recovers current state</li><li><code>getPresence</code> — snapshot current board members</li></ul><h2 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;Notes&quot;">​</a></h2><p>The 60 fps throttle is a client-side concern in the real Ably SDK — this dogfood implements the same 16 ms window in <code>mock.ts</code> <code>moveCursor</code> so the fidelity harness can score the emitted / suppressed ratio as an observable behaviour, not a hidden implementation detail. The throttle sits on a synthetic time cursor (raw event gaps summed) so tests are deterministic regardless of wall-clock timing, but the emitted <code>CursorPosition.timestamp</code> uses <code>Date.now()</code> at publish time so mock / real-mode payloads stay comparable when the SDK is wired.</p><p>The history rewind flow (<code>lateJoinerRewind</code>) exercises Ably&#39;s <code>channel.history()</code> shape. The mock ring buffer (<code>packages/realtime/src/ably.ts</code> — 200-event window) returns most-recent-first, matching Ably&#39;s real behaviour so a client replaying missed strokes sees them in the same order as production. <code>T-DFA-M-010</code> asserts monotonically non-increasing wall-clock timestamps to lock this invariant against future regressions.</p><p>The <code>twoUsersCollab</code> flow uses a single adapter (= single Ably client) as a mock-only convenience. In real Ably, <code>presence.enter(data)</code> identifies a member by the client-authenticated <code>clientId</code> — a single client cannot represent two distinct presence members. The mock stays internally consistent because the adapter maintains its own <code>membersByBoard</code> map keyed by caller-supplied <code>userId</code>, but the flow does NOT reflect real Ably multi-user semantics. Wiring a real-Ably-faithful two-user flow is a follow-up when the SDK is vendored: instantiate two <code>AblyMock</code> clients (each with distinct <code>clientId</code>) and drive them in parallel.</p><p>Provider prefix <code>@kiwa/realtime/</code> triggers the common 7-axis branch of <code>evaluateReleaseGate</code> (<code>packages/quality-metrics/src/gate.ts</code>). The AI-LLM 4 axes (cost / latency / token / accuracy) do not apply because Ably is a socket / pub-sub primitive, not a token-priced generative call. Socket round-trip latency feeds <code>perf.p95Ms</code> so realtime performance stays visible in the report.</p>`,20)])])}const b=t(i,[["render",r]]);export{u as __pageData,b as default};
